    private void connect(String address,int port,int slot,String password,String token)throws Exception{client=new NetworkClient(address,port,slot,password,token,id->settings.getProperty("campaignToken."+id+"."+slot,token));await(()->client.welcomed||!client.error.isEmpty(),7000);if(!client.welcomed)throw new java.io.IOException(client.error.isEmpty()?"Хост не ответил":client.error);}
