    private void saveToken(){var active=client;if(active==null||endpoint.isEmpty()||active.token.isEmpty())return;String key="token."+endpoint,campaignKey="campaignToken."+active.campaignId+"."+active.slot;if(active.token.equals(settings.getProperty(key))&&active.token.equals(settings.getProperty(campaignKey)))return;settings.setProperty(key,active.token);settings.setProperty(campaignKey,active.token);saveSettings();}
    private void saveSettings(){var copy=new Properties();copy.putAll(settings);files.submit(()->{try(var out=Files.newOutputStream(data.resolve("settings.properties"))){copy.store(out,"HIVE13 settings; private reconnect tokens");}catch(Exception e){System.err.println("Настройки не сохранены: "+e.getMessage());}});}
